package bergdb.core;

import bergdb.dag.KeyNode;
import bergdb.dag.TopNode;

/**
 * Runs TransSeq.take on cases generated by SplitMix64 from the case number, for the Lean
 * model's javaTake (bergdb 007-08), and prints the number of transactions taken in each
 * case; lean/SIS/BoundExample.lean makes the same cases as streams of the model, with the
 * same generator (takeCase), and compares (javaTakes there is this program's output for 300
 * cases). With the argument "fp", it prints TransSeq.ditherFp and TransSeq.shareFp, the take's
 * integer arithmetic since bergdb 005-79, for the checks there (its #guards of ditherFp and
 * shareFp).
 *
 * A case: records R(0), ..., R(s), s = a - 1, then the TransSeq, T(s+1), ..., T(s+n); each
 * record has own bytes 48 + below(400) and a size of its own bytes and below(3000); each
 * transaction of the TransSeq has below(30) got-dirty nodes; the setting is 10 + below(SDMAX),
 * SDMAX = 16000 (-Dsdmax); the record's own bytes 48 + below(400). The record limit is not
 * used (maxBytes = Long.MAX_VALUE), as in the model.
 *
 * With the argument "check" it compares instead of printing: the 300 cases with EXPECTED,
 * and ditherFp and shareFp with FP_EXPECTED, the same numbers as javaTakes and the #guards of
 * ditherFp and shareFp in lean/SIS/BoundExample.lean, which lake build compares with the
 * model's javaTake, ditherFp and shareFp. So Java's take and the model's give the same result
 * on these cases as long as both pass; a change of the take's arithmetic changes both lists.
 * It prints TAKECHECK OK, or TAKECHECK FAILED with the first difference and exits with
 * status 1. level2.sh runs it in its step 7, with lake build (bergdb 024-09, step A4).
 *
 * Usage: java -ea -cp build/bergdb.jar:build/stress bergdb.core.TakeCheck 300
 *        java -ea -cp build/bergdb.jar:build/stress bergdb.core.TakeCheck fp
 *        java -ea -cp build/bergdb.jar:build/stress bergdb.core.TakeCheck check
 *
 * From bergdb 007-08 (2026-10-28), where it printed the bits of the double rule's dither
 * and share ("bits"), which 005-79 removed from TransSeq; here, with "fp" in its place,
 * since bergdb 024-09 (2026-11-11; 015-03, 015-19), so that the build keeps it compiling.
 * In package bergdb.core to reach TransSeq.
 */
public class TakeCheck {
    static int SDMAX = Integer.getInteger("sdmax", 16000);
    static long state;

    /** The transactions taken in cases 0 to 299: javaTakes of lean/SIS/BoundExample.lean. */
    static final int[] EXPECTED = {
        0, 2, 1, 0, 3, 5, 1, 3, 2, 6, 4, 0, 0, 5, 1, 0, 9, 2, 0, 0, 1, 5, 2, 1, 1, 2, 0, 2, 0, 4,
        3, 7, 5, 2, 0, 0, 1, 2, 1, 0, 3, 1, 1, 1, 2, 0, 10, 3, 1, 1, 0, 1, 3, 3, 2, 1, 0, 3, 1, 1,
        0, 0, 4, 4, 2, 7, 2, 1, 2, 1, 2, 0, 1, 1, 1, 2, 4, 5, 1, 5, 1, 7, 2, 2, 2, 2, 0, 0, 2, 4,
        3, 3, 1, 1, 2, 0, 1, 0, 1, 2, 12, 0, 0, 0, 2, 3, 0, 3, 3, 0, 3, 5, 2, 3, 2, 1, 1, 1, 0, 3,
        1, 4, 1, 4, 2, 3, 4, 2, 1, 1, 2, 1, 7, 0, 1, 1, 1, 0, 4, 3, 4, 3, 2, 2, 1, 0, 8, 11, 0, 2,
        2, 0, 3, 3, 1, 1, 3, 4, 3, 3, 0, 4, 3, 3, 1, 1, 0, 0, 2, 2, 3, 0, 4, 2, 0, 1, 4, 2, 2, 1,
        3, 4, 2, 2, 2, 0, 5, 0, 0, 2, 1, 0, 0, 5, 0, 0, 1, 2, 0, 2, 1, 1, 2, 2, 0, 2, 2, 2, 1, 0,
        2, 0, 1, 2, 3, 2, 5, 3, 3, 2, 2, 1, 2, 2, 1, 2, 0, 1, 2, 1, 0, 1, 4, 0, 6, 1, 3, 3, 1, 2,
        4, 1, 5, 0, 1, 4, 0, 1, 2, 3, 1, 2, 2, 1, 0, 1, 2, 3, 0, 0, 1, 0, 3, 2, 2, 2, 7, 0, 2, 2,
        5, 1, 2, 3, 6, 1, 1, 2, 1, 0, 5, 9, 3, 2, 1, 3, 0, 0, 5, 0, 0, 3, 2, 0, 5, 0, 1, 0, 1, 2
    };

    /** The stream positions and the cases (D, o, O, S, sd) of "fp", and Java's results: the
     *  #guards of ditherFp and shareFp in lean/SIS/BoundExample.lean. */
    static final long[] FP_POS = {0, 1, 1200, 1300, 123456789L, 50000000000L, 9007199254740993L,
            531776};
    static final int[] FP_DITHER = {0, 57888, 65167, 26583, 39952, 51358, 35866, 49606};
    static final long[][] FP_CASES = {{100, 100, 1000, 2000, 800}, {7, 333, 1001, 12345, 997},
            {123457, 48, 9999991, 50000017, 50000000}, {6, 1000, 1000, 49606, 65536},
            {1000, 48, 48, 1L << 40, 10}, {0, 48, 1000, 2000, 800},
            {1L << 32, 48, 1000, 2000, 800}, {5, 1L << 31, 1000, 2000, 800},
            {5, 48, 1000, 1L << 47, 800}, {5, 48, 0, 2000, 800}, {5, 48, 1000, 2000, 0}};
    static final long[] FP_SHARE = {1638400, 458752, 38836, 297636, 65536000, 0,
            Long.MAX_VALUE, Long.MAX_VALUE, Long.MAX_VALUE, Long.MAX_VALUE, Long.MAX_VALUE};

    static long next() {
        long z = (state += 0x9E3779B97F4A7C15L);
        z = (z ^ (z >>> 30)) * 0xBF58476D1CE4E5B9L;
        z = (z ^ (z >>> 27)) * 0x94D049BB133111EBL;
        return z ^ (z >>> 31);
    }

    static int below(int k) {
        return (int) Long.remainderUnsigned(next(), k);
    }

    static final TransSeq.TransNodesForMe IGNORE = new TransSeq.TransNodesForMe() {
        public void addTopNode(TopNode node) {}
        public void addKeyNode(KeyNode node) {}
    };

    public static void main(String[] args) {
        if (args[0].equals("fp")) {
            // TransSeq.ditherFp and TransSeq.shareFp, in units of 2^-16.
            StringBuilder b = new StringBuilder();
            for (long p : FP_POS) {
                b.append(b.length() == 0 ? "" : ", ").append(TransSeq.ditherFp(p));
            }
            System.out.println("ditherFp: [" + b + "]");
            for (long[] c : FP_CASES) {
                System.out.println("shareFp " + c[0] + " " + c[1] + " " + c[2] + " " + c[3] + " "
                        + c[4] + ": " + TransSeq.shareFp(c[0], c[1], c[2], c[3], (int) c[4]));
            }
            return;
        }
        final boolean check = args[0].equals("check");
        if (check) {
            for (int i = 0; i < FP_POS.length; i++) {
                if (TransSeq.ditherFp(FP_POS[i]) != FP_DITHER[i]) {
                    System.out.println("TAKECHECK FAILED: ditherFp(" + FP_POS[i] + ") is "
                            + TransSeq.ditherFp(FP_POS[i]) + ", expected " + FP_DITHER[i]);
                    System.exit(1);
                }
            }
            for (int i = 0; i < FP_CASES.length; i++) {
                final long[] c = FP_CASES[i];
                final long r = TransSeq.shareFp(c[0], c[1], c[2], c[3], (int) c[4]);
                if (r != FP_SHARE[i]) {
                    System.out.println("TAKECHECK FAILED: shareFp " + c[0] + " " + c[1] + " " + c[2]
                            + " " + c[3] + " " + c[4] + " is " + r + ", expected " + FP_SHARE[i]);
                    System.exit(1);
                }
            }
        }
        int cases = check ? EXPECTED.length : Integer.parseInt(args[0]);
        StringBuilder sb = new StringBuilder();
        int middle = 0, nonEmpty = 0, atSpan = 0, byDeadline = 0, byShareOnly = 0, moreThanDeadline = 0;
        for (int c = 0; c < cases; c++) {
            state = c;
            int a = 1 + below(4);
            int n = below(13);
            int sd = 10 + below(SDMAX);
            long o = 48 + below(400);
            below(5);                       // got-dirty nodes of T(i), for the model's D only
            TransSeq s = new TransSeq();
            long[] tposes = new long[n];
            long p = 0;
            long currentSp = 0;
            for (int j = 0; j < a + n; j++) {
                long own = 48 + below(400);
                long size = own + below(3000);
                if (j == a - 1) {
                    currentSp = p;
                }
                if (j >= a) {
                    int count = below(30);
                    TransSeq.TransInfo info = new TransSeq.TransInfo();
                    info.tpos = p;
                    tposes[j - a] = p;
                    info.lastPos = p + size - 1;
                    info.ownBytes = own;
                    for (int k = 0; k < count; k++) {
                        KeyNode node = new KeyNode();
                        node.setDirty(true);
                        info.gotDirtyNodes.add(node);
                    }
                    s.add(info);
                }
                p += size;
            }
            long streamLength = p;
            int before = s.getSize();
            long hardSp = streamLength - Math.max(2L * sd, s.span());
            int due = 0;                    // the transactions the deadline takes
            for (long t : tposes) {
                if (t <= hardSp) due++;
            }
            if (before > 0) nonEmpty++;
            if (before > 0 && s.span() > 2L * sd) atSpan++;
            s.take(currentSp, streamLength, sd, o, IGNORE, Long.MAX_VALUE);
            int taken = before - s.getSize();
            if (due > 0) byDeadline++;
            if (due == 0 && taken > 0) byShareOnly++;
            if (taken > due) moreThanDeadline++;
            if (taken < before && taken > due) middle++;
            sb.append(taken);
            sb.append(c + 1 < cases ? ", " : "");
            if (check && taken != EXPECTED[c]) {
                System.out.println("TAKECHECK FAILED: case " + c + " takes " + taken
                        + " transactions, expected " + EXPECTED[c]);
                System.exit(1);
            }
        }
        if (check) {
            System.out.println("TAKECHECK OK (" + cases + " cases, " + FP_POS.length
                    + " dithers, " + FP_CASES.length + " shares)");
            return;
        }
        System.out.println("[" + sb + "]");
        System.err.println("cases " + cases + ", TransSeq not empty " + nonEmpty
                + ", span > 2 sd " + atSpan + ", the deadline takes some " + byDeadline
                + ", the share alone takes some " + byShareOnly
                + ", the share takes more than the deadline " + moreThanDeadline
                + ", the share stops before the end " + middle);
    }
}
